import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:go_router/go_router.dart'  import 'package:mobile_scanner/mobile_scanner.dart'  import '../api/api_client.dart'  import '../widgets/loading_widget.dart'    class ReceiptCheckScreen extends ConsumerStatefulWidget {    const ReceiptCheckScreen({super.key})      @override    ConsumerState<ReceiptCheckScreen> createState() => _ReceiptCheckScreenState()  }    class _ReceiptCheckScreenState extends ConsumerState<ReceiptCheckScreen> {    bool _isScanning = false    bool _isChecking = false    Map<String, dynamic>? _receiptData    String? _error      Future<void> _checkReceipt(String qrData) async {      setState(() {        _isChecking = true        _error = null        _receiptData = null      })        try {        // Парсим QR-код чека ФНС        // Формат: t=20240101T0000&s=1000.00&fn=1234567890&i=1&fp=1234567890&n=1        final params = Uri.parse('https://check.ru?$qrData').queryParameters          final receiptData = {          'date': params['t'],          'sum': params['s'],          'fn': params['fn'],          'fd': params['i'],          'fp': params['fp'],          'type': params['n'],        }          // TODO: интеграция с API ФНС для проверки        await Future.delayed(const Duration(seconds: 1))          setState(() {          _receiptData = receiptData          _isChecking = false        })      } catch (e) {        setState(() {          _error = 'Неверный формат QR-кода'          _isChecking = false        })      }    }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(title: const Text('Проверка чека ФНС')),        body: _isScanning            ? _buildScanner()            : _receiptData != null                ? _buildResult()                : _buildInitial(),      )    }      Widget _buildInitial() {      return Center(        child: Padding(          padding: const EdgeInsets.all(32),          child: Column(            mainAxisSize: MainAxisSize.min,            children: [              Icon(Icons.qr_code_scanner, size: 80, color: Colors.grey[300]),              const SizedBox(height: 24),              const Text(                'Проверка чеков ФНС',                style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold),              ),              const SizedBox(height: 12),              Text(                'Отсканируйте QR-код на чеке для проверки подлинности и получения данных',                style: TextStyle(fontSize: 14, color: Colors.grey[600]),                textAlign: TextAlign.center,              ),              const SizedBox(height: 32),              ElevatedButton.icon(                onPressed: () => setState(() => _isScanning = true),                icon: const Icon(Icons.qr_code_scanner),                label: const Text('Сканировать QR-код'),                style: ElevatedButton.styleFrom(                  padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 16),                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),                ),              ),            ],          ),        ),      )    }      Widget _buildScanner() {      return Stack(        children: [          MobileScanner(            onDetect: (capture) {              final barcodes = capture.barcodes              if (barcodes.isNotEmpty && barcodes.first.rawValue != null) {                final data = barcodes.first.rawValue!                setState(() => _isScanning = false)                _checkReceipt(data)              }            },          ),          Positioned(            top: 16,            right: 16,            child: IconButton(              icon: const Icon(Icons.close, color: Colors.white, size: 32),              onPressed: () => setState(() => _isScanning = false),            ),          ),          Center(            child: Container(              width: 250,              height: 250,              decoration: BoxDecoration(                border: Border.all(color: Colors.white, width: 2),                borderRadius: BorderRadius.circular(16),              ),            ),          ),          const Positioned(            bottom: 40,            left: 0,            right: 0,            child: Text(              'Наведите камеру на QR-код чека',              textAlign: TextAlign.center,              style: TextStyle(color: Colors.white, fontSize: 16, shadows: [Shadow(color: Colors.black, blurRadius: 4)]),            ),          ),        ],      )    }      Widget _buildResult() {      return SingleChildScrollView(        padding: const EdgeInsets.all(16),        child: Column(          crossAxisAlignment: CrossAxisAlignment.stretch,          children: [            if (_error != null)              Card(                color: Colors.red[50],                child: Padding(                  padding: const EdgeInsets.all(16),                  child: Row(                    children: [                      Icon(Icons.error_outline, color: Colors.red[700]),                      const SizedBox(width: 12),                      Expanded(child: Text(_error!, style: TextStyle(color: Colors.red[700]))),                    ],                  ),                ),              )            else ...[              const Icon(Icons.check_circle, size: 64, color: Colors.green),              const SizedBox(height: 16),              const Text('Чек найден', style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold), textAlign: TextAlign.center),              const SizedBox(height: 24),              _ReceiptField(label: 'Дата', value: _receiptData!['date'] ?? '—'),              _ReceiptField(label: 'Сумма', value: '${_receiptData!['sum'] ?? '—'} ₽'),              _ReceiptField(label: 'ФН', value: _receiptData!['fn'] ?? '—'),              _ReceiptField(label: 'ФД', value: _receiptData!['fd'] ?? '—'),              _ReceiptField(label: 'ФП', value: _receiptData!['fp'] ?? '—'),              _ReceiptField(label: 'Тип', value: _receiptData!['type'] == '1' ? 'Приход' : 'Расход'),              const SizedBox(height: 24),              ElevatedButton.icon(                onPressed: () => setState(() {                  _receiptData = null                  _error = null                }),                icon: const Icon(Icons.qr_code_scanner),                label: const Text('Сканировать еще'),                style: ElevatedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16)),              ),            ],          ],        ),      )    }  }    class _ReceiptField extends StatelessWidget {    final String label    final String value      const _ReceiptField({required this.label, required this.value})      @override    Widget build(BuildContext context) {      return Card(        margin: const EdgeInsets.only(bottom: 8),        child: ListTile(          title: Text(label, style: TextStyle(fontSize: 12, color: Colors.grey[600])),          subtitle: Text(value, style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),        ),      )    }  }